41-fn write_swallowing_broken_pipe<W: Write>(w: &mut W, bytes: &[u8]) -> io::Result<()> {
42-    match w.write_all(bytes) {
43-        Ok(()) => Ok(()),
44-        Err(e) if e.kind() == io::ErrorKind::BrokenPipe => Ok(()),
