75	            entries.push(ReleaseDecisionEntry {
76	                package: id.clone(),
77	                target_version: bump.to.clone(),
78	                reasons: vec![reason_from_bump(bump.reason.as_ref(), &package_ids)?],
79	            });
80	        }
81	    }
82	    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
83	}
