85	/// Derives a durable decision for explicit, exact release identities.
86	///
87	/// A linked group is one release unit: selecting any member includes every
88	/// member of that linked group which the version plan selected. All other
89	/// packages remain outside the authority boundary. The caller must pass
90	/// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
91	/// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
92	/// for release authority.
93	pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
94	    workspace: &Workspace<'_, R, D>,
95	    plan: &VersionPlan,
96	    selections: &[ReleasePackageId],
97	) -> Result<ReleaseDecisionV1, GraphError> {
98	    let complete = derive_release_decision(workspace, plan)?;
99	
100	    let mut seen = std::collections::BTreeSet::new();
101	    if let Some(duplicate) = selections.iter().find(|selection| !seen.insert(*selection)) {
102	        return Err(GraphError::ReleaseSelectionInvalid {
103	            package: duplicate.clone(),
104	            reason: ReleaseSelectionInvalidReason::Duplicate,
105	        });
106	    }
107	
108	    let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
109	    for selection in &selected {
110	        let Some(package) = workspace_package(workspace, selection) else {
111	            return Err(GraphError::UnknownPackage {
112	                id: callisto_model::PackageId::Prefixed {
113	                    ecosystem: selection.ecosystem(),
114	                    name: selection.name().to_string(),
115	                },
116	            });
117	        };
118	        let reason = if !complete.entries.iter().any(|entry| &entry.package == *selection) {
119	            ReleaseSelectionInvalidReason::NotARelease
120	        } else if package
121	            .publish_to
122	            .iter()
123	            .all(|target| matches!(target, callisto_model::PublishTarget::None))
124	        {
125	            ReleaseSelectionInvalidReason::NoDispatchableTarget
126	        } else {
127	            continue;
128	        };
129	        return Err(GraphError::ReleaseSelectionInvalid {
130	            package: (*selection).clone(),
131	            reason,
132	        });
133	    }
134	
135	    let entries = expand_selection(workspace, complete.entries, &selected);
136	    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
137	}
