139	/// Keeps the selected entries plus every entry sharing a fixed or linked group
140	/// with a selection. Both release routes narrow `--package` through this.
141	fn expand_selection<R: callisto_model::CommandRunner, D: DependencyResolver>(
142	    workspace: &Workspace<'_, R, D>,
143	    entries: Vec<ReleaseDecisionEntry>,
144	    selected: &std::collections::BTreeSet<&ReleasePackageId>,
145	) -> Vec<ReleaseDecisionEntry> {
146	    // A plan-derived entry carries its linked group as a reason.
147	    let reason_groups = entries
148	        .iter()
149	        .filter(|entry| selected.contains(&entry.package))
150	        .flat_map(|entry| entry.reasons.iter())
151	        .filter_map(|reason| match reason {
152	            ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
153	            _ => None,
154	        })
155	        .collect::<std::collections::BTreeSet<_>>();
156	    // Config membership: a selected member's own reason is often `Changeset` or `UnreleasedVersion`.
157	    let config_groups = selected
158	        .iter()
159	        .flat_map(|selection| release_groups_of(workspace, selection))
160	        .collect::<std::collections::BTreeSet<_>>();
161	    // Selecting one distribution of a package releases all of them, so the shared tag waits for every publish.
162	    let selected_packages = selected
163	        .iter()
164	        .filter_map(|selection| workspace_package(workspace, selection))
165	        .map(|package| package.id.clone())
166	        .collect::<std::collections::BTreeSet<_>>();
167	    entries
168	        .into_iter()
169	        .filter(|entry| {
170	            selected.contains(&entry.package)
171	                || workspace_package(workspace, &entry.package).is_some_and(|package| selected_packages.contains(&package.id))
172	                || entry.reasons.iter().any(|reason| {
173	                    matches!(reason, ReleaseInclusionReason::LinkedGroup { group_id } if reason_groups.contains(group_id))
174	                })
175	                || release_groups_of(workspace, &entry.package)
176	                    .iter()
177	                    .any(|group| config_groups.contains(group))
178	        })
179	        .collect()
180	}
