197	/// does not prove the rest of the release was observed.
198	pub(crate) fn derive_release_roster<R: callisto_model::CommandRunner, D: DependencyResolver>(
199	    workspace: &Workspace<'_, R, D>,
200	    selections: &[ReleasePackageId],
201	    resumable: &std::collections::BTreeSet<ReleasePackageId>,
202	) -> Result<Option<ReleaseDecisionV1>, GraphError> {
203	    let versions = workspace.base_versions()?;
204	    let tags = workspace.tags()?;
205	    let mut entries = Vec::new();
206	    for package in workspace.graph.packages() {
207	        if !has_dispatchable_target(package) {
208	            continue;
209	        }
210	        let version = versions.get(&package.id).ok_or_else(|| GraphError::ReleaseInvariant {
211	            detail: format!("package `{}` has no base version", package.id.display_name()),
212	        })?;
213	        let ids = release_package_ids(&workspace.identity, package)?;
214	        if version_is_tagged(tags, &package.id, version) && !ids.iter().any(|id| resumable.contains(id)) {
215	            continue;
216	        }
217	        for id in ids {
218	            entries.push(ReleaseDecisionEntry {
219	                package: id,
220	                target_version: version.clone(),
221	                reasons: vec![ReleaseInclusionReason::UnreleasedVersion],
222	            });
223	        }
224	    }
225	
226	    let mut seen = std::collections::BTreeSet::new();
227	    for selection in selections {
228	        if !seen.insert(selection) {
229	            return Err(GraphError::ReleaseSelectionInvalid {
230	                package: selection.clone(),
231	                reason: ReleaseSelectionInvalidReason::Duplicate,
232	            });
233	        }
234	        let Some(package) = workspace_package(workspace, selection) else {
235	            return Err(GraphError::UnknownPackage {
236	                id: callisto_model::PackageId::Prefixed {
237	                    ecosystem: selection.ecosystem(),
238	                    name: selection.name().to_string(),
239	                },
240	            });
241	        };
242	        if !has_dispatchable_target(package) {
243	            return Err(GraphError::ReleaseSelectionInvalid {
244	                package: selection.clone(),
245	                reason: ReleaseSelectionInvalidReason::NoDispatchableTarget,
246	            });
247	        }
248	        if !entries.iter().any(|entry| &entry.package == selection) {
249	            return Err(GraphError::ReleaseSelectionInvalid {
250	                package: selection.clone(),
251	                reason: ReleaseSelectionInvalidReason::NotARelease,
252	            });
253	        }
254	    }
255	    if !selections.is_empty() {
256	        entries = expand_selection(workspace, entries, &seen);
257	    }
258	    if entries.is_empty() {
259	        return Ok(None);
260	    }
261	    ReleaseDecisionV1::new(entries).map(Some).map_err(GraphError::from)
262	}
