287	/// Entries for every publishable package whose current version is tagged on `source`.
288	///
289	/// A run that created such a tag may have stopped before pushing it or finishing the release.
290	pub(crate) fn releases_tagged_at<R: callisto_model::CommandRunner, D: DependencyResolver>(
291	    workspace: &Workspace<'_, R, D>,
292	    source: &CommitSha,
293	) -> Result<Vec<ReleaseDecisionEntry>, GraphError> {
294	    let versions = workspace.base_versions()?;
295	    let tags = workspace.tags()?;
296	    let git = workspace.git_access();
297	    let mut entries = Vec::new();
298	    for package in workspace.graph.packages() {
299	        if !has_dispatchable_target(package) {
300	            continue;
301	        }
302	        let Some(version) = versions.get(&package.id) else {
303	            continue;
304	        };
305	        // Only the tag this run's tag operation would create: one made under an older template is another release's.
306	        let tag = tags.template(&package.id).render(version).to_string();
307	        if !tags.contains_tag(&tag) {
308	            continue;
309	        }
310	        if tags.commit_of(git, &tag)?.as_ref() != Some(source) {
311	            continue;
312	        }
313	        for id in release_package_ids(&workspace.identity, package)? {
314	            entries.push(ReleaseDecisionEntry {
315	                package: id,
316	                target_version: version.clone(),
317	                reasons: vec![ReleaseInclusionReason::UnreleasedVersion],
318	            });
319	        }
320	    }
321	    Ok(entries)
322	}
